-- Insert Quiz Questions for Lesson: Real-World Practice Exercise

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'real-world-practice' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson real-world-practice not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Should the person in the scenario be added as an Opportunity?', 
    '["No, they are not serious","Yes, they showed interest in a service","Only if they pay first","No, leave them in the inbox"]'::jsonb,
    'Yes, they showed interest in a service',
    'Yes, they should be added as an Opportunity because they showed interest in a service. Anyone who could become a client should be tracked as an Opportunity.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a good next action for the scenario?', 
    '["Ignore the message","Send a short reply and invite them to book a call","Wait for them to contact again","Delete the message"]'::jsonb,
    'Send a short reply and invite them to book a call',
    'A good next action is to send a short reply and invite them to book a call. This continues the conversation and moves them toward becoming a client.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What makes the system useful?', 
    '["Reading about it","Using it with real leads","Setting it up once and forgetting it","Having many empty stages"]'::jsonb,
    'Using it with real leads',
    'The system only becomes useful when you actually use it with real leads. Theory and setup are important, but practical application is what brings results.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
